import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const r="/img/encounter-pursuit-logic.svg",g=JSON.parse('{"title":"小学奥数专项：相遇与追及问题初步（速度和与速度差）","description":"","frontmatter":{"title":"小学奥数专项：相遇与追及问题初步（速度和与速度差）","date":"2026-02-27T15:30:00.000Z","tags":["奥数","四年级","行程问题"],"categories":["教育","数学"]},"headers":[],"relativePath":"posts/primary-math-olympiad-encounter-pursuit.md","filePath":"posts/primary-math-olympiad-encounter-pursuit.md","lastUpdated":null}'),o={name:"posts/primary-math-olympiad-encounter-pursuit.md"};function l(p,a,e,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="相遇与追及-多个物体的运动逻辑" tabindex="-1">相遇与追及：多个物体的运动逻辑 <a class="header-anchor" href="#相遇与追及-多个物体的运动逻辑" aria-label="Permalink to &quot;相遇与追及：多个物体的运动逻辑&quot;">​</a></h1><p>在掌握了单个物体的行程基础后，我们要进入更有趣的领域：<strong>多个物体的运动</strong>。当两个物体同时运动时，它们之间的距离会发生变化。研究这种距离变化规律的问题，就是相遇与追及问题。</p><h2 id="_1-核心模型图解" tabindex="-1">1. 核心模型图解 <a class="header-anchor" href="#_1-核心模型图解" aria-label="Permalink to &quot;1. 核心模型图解&quot;">​</a></h2><p>我们将复杂的运动简化为两个核心模型：</p><ul><li><strong>相遇问题：</strong> 两个物体<strong>面对面</strong>运动，距离越来越近。</li><li><strong>追及问题：</strong> 两个物体<strong>同向</strong>运动，后面的快车追赶前面的慢车，距离逐渐缩小。</li></ul><p><img src="'+r+'" alt="相遇与追及逻辑图"></p><hr><h2 id="_2-相遇问题-速度和" tabindex="-1">2. 相遇问题（速度和） <a class="header-anchor" href="#_2-相遇问题-速度和" aria-label="Permalink to &quot;2. 相遇问题（速度和）&quot;">​</a></h2><h3 id="_2-1-核心公式" tabindex="-1">2.1 核心公式 <a class="header-anchor" href="#_2-1-核心公式" aria-label="Permalink to &quot;2.1 核心公式&quot;">​</a></h3><p>当两人相对而行时，单位时间内两人走过的路程之和，称为<strong>速度和</strong>。</p><ol><li><strong>路程和 = 速度和 × 相遇时间</strong></li><li><strong>相遇时间 = 路程和 ÷ 速度和</strong></li><li><strong>速度和 = 路程和 ÷ 相遇时间</strong></li></ol><h3 id="_2-2-经典例题" tabindex="-1">2.2 经典例题 <a class="header-anchor" href="#_2-2-经典例题" aria-label="Permalink to &quot;2.2 经典例题&quot;">​</a></h3><p><strong>题目：</strong> 甲、乙两地相距 480 千米。一列快车从甲地开往乙地，每小时行 70 千米；一列慢车从乙地开往甲地，每小时行 50 千米。两车同时出发，经过几小时相遇？</p><p><strong>【分析】</strong></p><ul><li>这是一个典型的相遇问题。</li><li>路程和 = 480 千米。</li><li>速度和 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>7</mn><mn>0</mn><mo>+</mo><mn>5</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">70 + 50 = 120</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span> 千米/小时。</li></ul><p><strong>【解题】</strong><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>8</mn><mn>0</mn><mo>÷</mo><mo>(</mo><mn>7</mn><mn>0</mn><mo>+</mo><mn>5</mn><mn>0</mn><mo>)</mo><mo>=</mo><mn>4</mn><mn>8</mn><mn>0</mn><mo>÷</mo><mn>1</mn><mn>2</mn><mn>0</mn><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">480 \\div (70 + 50) = 480 \\div 120 = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">7</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">8</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>（小时）。 <strong>答：</strong> 两车经过 4 小时相遇。</p><hr><h2 id="_3-追及问题-速度差" tabindex="-1">3. 追及问题（速度差） <a class="header-anchor" href="#_3-追及问题-速度差" aria-label="Permalink to &quot;3. 追及问题（速度差）&quot;">​</a></h2><h3 id="_3-1-核心公式" tabindex="-1">3.1 核心公式 <a class="header-anchor" href="#_3-1-核心公式" aria-label="Permalink to &quot;3.1 核心公式&quot;">​</a></h3><p>当两人同向而行时，单位时间内快者比慢者多走的路程，称为<strong>速度差</strong>。</p><ol><li><strong>路程差 = 速度差 × 追及时间</strong></li><li><strong>追及时间 = 路程差 ÷ 速度差</strong></li><li><strong>速度差 = 路程差 ÷ 追及时间</strong></li></ol><h3 id="_3-2-经典例题" tabindex="-1">3.2 经典例题 <a class="header-anchor" href="#_3-2-经典例题" aria-label="Permalink to &quot;3.2 经典例题&quot;">​</a></h3><p><strong>题目：</strong> 弟弟以每秒 2 米的速度走路，出发 1 分钟后，哥哥发现弟弟忘了带文具盒，立即以每秒 5 米的速度骑车去追。哥哥需要多少秒才能追上弟弟？</p><p><strong>【分析】</strong></p><ul><li>这是一个追及问题。</li><li><strong>关键点：</strong> 路程差是多少？路程差是哥哥出发前，弟弟已经走过的距离。</li><li>路程差 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>6</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2 \\times 60 = 120</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span> 米。</li><li>速度差 = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>−</mo><mn>2</mn><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">5 - 2 = 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span> 米/秒。</li></ul><p><strong>【解题】</strong></p><ol><li>路程差：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mn>6</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">2 \\times 60 = 120</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>（米）。</li><li>追及时间：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mo>(</mo><mn>5</mn><mo>−</mo><mn>2</mn><mo>)</mo><mo>=</mo><mn>1</mn><mn>2</mn><mn>0</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">120 \\div (5 - 2) = 120 \\div 3 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">5</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>（秒）。 <strong>答：</strong> 哥哥需要 40 秒追上弟弟。</li></ol><hr><h2 id="_4-引导性思考-变式应用" tabindex="-1">4. 引导性思考：变式应用 <a class="header-anchor" href="#_4-引导性思考-变式应用" aria-label="Permalink to &quot;4. 引导性思考：变式应用&quot;">​</a></h2><h3 id="_4-1-二次相遇" tabindex="-1">4.1 二次相遇 <a class="header-anchor" href="#_4-1-二次相遇" aria-label="Permalink to &quot;4.1 二次相遇&quot;">​</a></h3><p>如果甲乙两人相向而行，相遇后继续前进，分别到达对方起点后立即返回。这叫“多次相遇”。 <strong>规律：</strong> 第二次相遇时，两人走过的总路程是甲乙两地距离的 <strong>3 倍</strong>。</p><h3 id="_4-2-环形跑道" tabindex="-1">4.2 环形跑道 <a class="header-anchor" href="#_4-2-环形跑道" aria-label="Permalink to &quot;4.2 环形跑道&quot;">​</a></h3><ul><li><strong>相向而行：</strong> 每次相遇，两人走过的路程和等于 <strong>一圈的长</strong>。</li><li><strong>同向而行：</strong> 每次追上（套圈），两人走过的路程差等于 <strong>一圈的长</strong>。</li></ul><hr><h2 id="_5-闯关练习" tabindex="-1">5. 闯关练习 <a class="header-anchor" href="#_5-闯关练习" aria-label="Permalink to &quot;5. 闯关练习&quot;">​</a></h2><ol><li><strong>基础关：</strong> A、B 两车同时从相距 300 千米的甲、乙两地相对开出。A 车速度 40km/h，B 车速度 60km/h，几小时相遇？</li><li><strong>进阶关：</strong> 小红每分钟走 50 米，小明每分钟走 70 米。小红先走 10 分钟后，小明从起点出发追赶。小明追上小红需要多少分钟？</li><li><strong>挑战关：</strong> 环形跑道长 400 米，小强每秒跑 6 米，小刚每秒跑 4 米。 <ul><li>若两人同时同地背向而行，几秒后第一次相遇？</li><li>若两人同时同地同向而行，几秒后小强第一次追上小刚？</li></ul></li></ol><hr><p><strong>数学笔记：</strong> 处理多个物体运动时，重点在于观察<strong>距离的变化量</strong>。相对运动用“和”，同向运动用“差”！</p>',38)])])}const u=s(o,[["render",l]]);export{g as __pageData,u as default};
